from __future__ import annotations

import time
from typing import Callable


def current_bucket(clock: Callable[[], float] = time.time) -> int:
    """The wall-clock second the caller is currently in."""
    return int(clock())


class RateLimiter:
    """Counts hits into whole-second buckets taken from the wall clock."""

    def __init__(self, budget: int, clock: Callable[[], float] = time.time) -> None:
        self.budget = budget
        self.clock = clock
        self._counts: dict[int, int] = {}

    def hit(self) -> int:
        """Record one hit and return the count within the current second."""
        bucket = current_bucket(self.clock)
        self._counts[bucket] = self._counts.get(bucket, 0) + 1
        return self._counts[bucket]

    def remaining(self) -> int:
        """Budget left in the current second."""
        return self.budget - self._counts.get(current_bucket(self.clock), 0)
